layer.css:
[data-ryt="footer"] { color: #939393; border-top: 1px solid rgb(54, 54, 54); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 2px solid rgb(122, 122, 122); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="brand"] { color: #929292; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="nav"] a { color: #929292; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 16px; font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 8px; padding-right: 12px; padding-bottom: 8px; padding-left: 12px; transition: all }
[data-ryt="button"] { color: rgb(219, 219, 219); background-color: var(--ryt-text); border-top: 1px solid rgb(219, 219, 219); border-right: 1px solid rgb(219, 219, 219); border-bottom: 1px solid rgb(219, 219, 219); border-left: 1px solid rgb(219, 219, 219); border-radius: 4px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; line-height: 1.5; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(219, 219, 219); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 7px; padding-right: 16px; padding-bottom: 7px; padding-left: 16px; transition: all }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: #8a8a8a; border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(181, 181, 181); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] { color: #929292; border-bottom: 2px solid rgb(122, 122, 122); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 32px; font-weight: 600; font-style: normal; line-height: 1.125; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-bg); text-decoration-thickness: auto; text-underline-offset: auto; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: rgb(54, 54, 54); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: gold }
[data-ryt="button"]:hover { border-top-color: rgb(181, 181, 181); border-right-color: rgb(181, 181, 181); border-bottom-color: rgb(181, 181, 181); border-left-color: rgb(181, 181, 181); color: skyblue }
[data-ryt="nav"] a:hover { color: rgb(54, 54, 54); background-color: rgb(250, 250, 250); color: rgb(72, 95, 199); background-color: rgb(41, 41, 41); text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial; color: gold }
